import type { ReactNode } from "react";

import type { DownloadableItemData } from "@procertus-ui/ui";

import type {
  PortalChatComposerToolbarOptions,
  PortalChatMessagePlacement,
} from "./portal-chat-types";

export type { PortalChatMessagePlacement as PortalEmailMessagePlacement } from "./portal-chat-types";

/** Attachment line in the thread or in the compose area — maps to `DownloadableItem`. */
export type PortalEmailAttachment = DownloadableItemData;

export type PortalEmailMessage = {
  id: string;
  placement: PortalChatMessagePlacement;
  authorLabel: string;
  /** ISO 8601; formatted via `formatTimestamp`. */
  atIso: string;
  body: string;
  /** Optional subject line — shown like an email subject when set. */
  subject?: string;
  attachments?: readonly PortalEmailAttachment[];
};

export type PortalEmailComposerProps = {
  show?: boolean;
  readOnly?: boolean;
  disabled?: boolean;
  placeholder?: string;
  value?: string;
  onChange?: (value: string) => void;
  className?: string;
  "aria-label"?: string;
  onSubmit?: () => void;
  toolbar?: boolean | PortalChatComposerToolbarOptions;
  /**
   * Optional subject for the outbound reply (shown above the body).
   * Omit handlers to hide the field.
   */
  subject?: string;
  onSubjectChange?: (value: string) => void;
  subjectPlaceholder?: string;
  /** When false, no subject row is rendered. Default true when `onSubjectChange` is set. */
  showSubjectField?: boolean;
  /**
   * Staged files for the next message — rendered inline above the textarea with optional remove.
   */
  pendingAttachments?: readonly PortalEmailAttachment[];
  onRemovePendingAttachment?: (id: string) => void;
  /** Called after the user picks local files — parent typically builds `blob:` URLs. */
  onPickFiles?: (files: readonly File[]) => void;
  pickFilesAccept?: string;
  pickFilesAriaLabel?: string;
  /** Hide emoji / mention affordances when composing email-style replies. */
  composeStyle?: "chat" | "email";
};

export type PortalEmailThreadSummary = {
  /** e.g. request / dossier title */
  title?: string;
  subtitle?: string;
};

export type PortalEmailThreadWindowProps = {
  messages: readonly PortalEmailMessage[];
  "aria-label"?: string;
  className?: string;
  scrollAreaClassName?: string;
  formatTimestamp?: (iso: string) => string;
  composer?: PortalEmailComposerProps;
  emptyContent?: ReactNode;
  /** Optional banner above the scroll area (conversation context). */
  threadSummary?: PortalEmailThreadSummary;
};

import { useCallback, useRef } from "react";
import { Attachment01Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";

import {
  Button,
  DownloadableItem,
  Input,
  Label,
  cn,
} from "@procertus-ui/ui";

import { ChatList } from "../../components/portal-chat/chat-list";
import type {
  PortalEmailComposerProps,
  PortalEmailMessage,
  PortalEmailThreadWindowProps,
} from "../../components/portal-chat/portal-email-thread-types";
import type { PortalChatComposerToolbarOptions } from "../../components/portal-chat/portal-chat-types";
import { ChatComposerToolbar } from "./chat-composer-toolbar";

const defaultFormatTimestamp = (iso: string) =>
  new Intl.DateTimeFormat("nl-BE", {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso));

function normalizeToolbarOptions(
  toolbar: PortalEmailComposerProps["toolbar"],
): PortalChatComposerToolbarOptions {
  if (toolbar == null || toolbar === false || toolbar === true) return {};
  return toolbar;
}

function EmailThreadComposer({
  readOnly,
  disabled,
  value,
  onChange,
  onSubmit,
  placeholder,
  "aria-label": ariaLabel,
  className,
  toolbar,
  subject,
  onSubjectChange,
  subjectPlaceholder = "Onderwerp",
  showSubjectField,
  pendingAttachments = [],
  onRemovePendingAttachment,
  onPickFiles,
  pickFilesAccept,
  pickFilesAriaLabel = "Bestand bijvoegen",
  composeStyle = "email",
}: PortalEmailComposerProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const toolbarOpts = normalizeToolbarOptions(toolbar);
  const effectiveShowSubject =
    showSubjectField !== false && onSubjectChange != null;

  const hideEmoji = composeStyle === "email" || toolbarOpts.hideEmojiPicker === true;
  const hideMention = composeStyle === "email" || toolbarOpts.hideMentionButton === true;

  const onFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const list = e.target.files;
      if (!list?.length || !onPickFiles) return;
      onPickFiles(Array.from(list));
      e.target.value = "";
    },
    [onPickFiles],
  );

  const sendBlocked =
    Boolean(disabled) ||
    Boolean(readOnly) ||
    toolbarOpts.sendDisabled === true ||
    (value ?? "").trim().length === 0;

  const submit = () => {
    if (sendBlocked) return;
    onSubmit?.();
  };

  return (
    <div className={cn("border-t border-border bg-card", className)}>
      {effectiveShowSubject ? (
        <div className="space-y-1.5 border-b border-border px-section py-3">
          <Label htmlFor="portal-email-thread-subject" className="text-xs text-muted-foreground">
            Onderwerp
          </Label>
          <Input
            id="portal-email-thread-subject"
            value={subject ?? ""}
            onChange={(e) => onSubjectChange?.(e.target.value)}
            placeholder={subjectPlaceholder}
            readOnly={readOnly}
            disabled={disabled}
            className="h-9"
          />
        </div>
      ) : null}

      {pendingAttachments.length > 0 ? (
        <div
          role="list"
          aria-label="Bijlagen voor uw antwoord"
          className="flex flex-col gap-micro border-b border-border px-section py-3"
        >
          {pendingAttachments.map((a) => (
            <DownloadableItem
              key={a.id}
              variant="row"
              {...a}
              onDelete={
                readOnly || !onRemovePendingAttachment
                  ? undefined
                  : () => onRemovePendingAttachment(a.id)
              }
            />
          ))}
        </div>
      ) : null}

      <input
        ref={fileInputRef}
        type="file"
        className="sr-only"
        tabIndex={-1}
        multiple
        accept={pickFilesAccept}
        aria-hidden
        onChange={onFileChange}
      />

      {!readOnly && onPickFiles ? (
        <div className="flex items-start gap-2 border-b border-border px-section pb-2 pt-3">
          <Button
            type="button"
            variant="outline"
            size="icon"
            disabled={disabled}
            aria-label={pickFilesAriaLabel}
            className="shrink-0"
            onClick={() => fileInputRef.current?.click()}
          >
            <HugeiconsIcon icon={Attachment01Icon} className="size-5" strokeWidth={1.5} />
          </Button>
          <div className="min-w-0 flex-1">
            <ChatComposerToolbar
              value={value ?? ""}
              onChange={(v) => onChange?.(v)}
              onSubmit={submit}
              placeholder={placeholder ?? "Schrijf uw bericht…"}
              disabled={disabled}
              readOnly={readOnly}
              aria-label={ariaLabel}
              inputClassName="border-0 bg-transparent px-0 shadow-none dark:bg-transparent"
              hideEmojiPicker={hideEmoji}
              hideMentionButton={hideMention}
              emojiPresets={toolbarOpts.emojiPresets}
              asForm={false}
              sendDisabled={toolbarOpts.sendDisabled}
              sendAriaLabel={toolbarOpts.sendAriaLabel ?? "Verzenden"}
              className={cn(
                "!p-0",
                "!border-t-0",
                "[html[data-storybook]&]:border-t-0",
              )}
            />
          </div>
        </div>
      ) : (
        <ChatComposerToolbar
          value={value ?? ""}
          onChange={(v) => onChange?.(v)}
          onSubmit={submit}
          placeholder={placeholder ?? "Schrijf uw bericht…"}
          disabled={disabled}
          readOnly={readOnly}
          aria-label={ariaLabel}
          hideEmojiPicker={hideEmoji}
          hideMentionButton={hideMention}
          emojiPresets={toolbarOpts.emojiPresets}
          asForm
          sendDisabled={toolbarOpts.sendDisabled}
          sendAriaLabel={toolbarOpts.sendAriaLabel ?? "Verzenden"}
          className="p-section"
        />
      )}
    </div>
  );
}

function MessageCard({
  m,
  formatTimestamp,
}: {
  m: PortalEmailMessage;
  formatTimestamp: (iso: string) => string;
}) {
  const isRequester = m.placement === "requester";

  return (
    <article
      aria-labelledby={`email-msg-${m.id}-heading`}
      className={cn(
        "rounded-lg border border-border bg-card text-card-foreground shadow-sm",
        isRequester
          ? "border-l-4 border-l-primary"
          : "border-l-4 border-l-muted-foreground/35",
      )}
    >
      <div className="border-b border-border/80 px-4 py-3">
        <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
          <h3 id={`email-msg-${m.id}-heading`} className="text-sm font-semibold leading-snug">
            {m.authorLabel}
          </h3>
          <time
            className="text-xs tabular-nums text-muted-foreground"
            dateTime={m.atIso}
          >
            {formatTimestamp(m.atIso)}
          </time>
        </div>
        {m.subject ? (
          <p className="mt-1 text-sm font-medium leading-snug text-foreground">{m.subject}</p>
        ) : null}
      </div>

      <div className="px-4 py-3">
        <div className="whitespace-pre-wrap text-sm leading-relaxed text-card-foreground">
          {m.body}
        </div>

        {m.attachments && m.attachments.length > 0 ? (
          <div
            role="list"
            aria-label="Bijlagen"
            className="mt-4 flex flex-col gap-micro border-t border-dashed border-border pt-4"
          >
            {m.attachments.map((a) => (
              <DownloadableItem key={a.id} variant="row" {...a} />
            ))}
          </div>
        ) : null}
      </div>
    </article>
  );
}

/**
 * Single-thread email-style transcript: timestamped cards with optional subjects,
 * inline attachments via `DownloadableItem`, and a compose area that supports file
 * picking and staged attachment rows above the textarea.
 */
export function PortalEmailThreadWindow({
  messages,
  "aria-label": ariaLabel = "Berichtendrad",
  className,
  scrollAreaClassName,
  formatTimestamp = defaultFormatTimestamp,
  composer,
  emptyContent,
  threadSummary,
}: PortalEmailThreadWindowProps) {
  const showComposer = composer?.show !== false;

  return (
    <div className={cn("flex min-h-0 min-w-0 flex-col gap-3 bg-card text-card-foreground", className)}>
      {threadSummary?.title || threadSummary?.subtitle ? (
        <header className="shrink-0 border-b border-border px-section pb-3 pt-1">
          {threadSummary.title ? (
            <h2 className="text-base font-semibold leading-tight">{threadSummary.title}</h2>
          ) : null}
          {threadSummary.subtitle ? (
            <p className="mt-1 text-xs text-muted-foreground">{threadSummary.subtitle}</p>
          ) : null}
        </header>
      ) : null}

      {messages.length === 0 ? (
        <div className="text-sm text-muted-foreground">
          {emptyContent ?? "Nog geen berichten in dit gesprek."}
        </div>
      ) : (
        <ChatList
          className={cn("gap-4 pb-2 pt-1", scrollAreaClassName)}
          role="log"
          aria-live="polite"
          aria-label={ariaLabel}
        >
          <div className="flex flex-col gap-4">
            {messages.map((m) => (
              <MessageCard key={m.id} m={m} formatTimestamp={formatTimestamp} />
            ))}
          </div>
        </ChatList>
      )}

      {showComposer ? <EmailThreadComposer {...composer} readOnly={composer?.readOnly ?? true} /> : null}
    </div>
  );
}

