import type { JSX, ReactNode } from "react";
import Markdown from "react-markdown";
import remarkGfm from "remark-gfm";

import { cn } from "@/lib/utils";

const inlineCodeClass =
  "rounded bg-muted px-1 py-0.5 font-mono text-[0.85em] text-foreground [&:not(div_code_*)]:underline-offset-4";

/** Allow only safe link schemes for rendered dossier markdown. */
function sanitizeHref(href: string | undefined): string | undefined {
  if (href == null || href.trim() === "") return undefined;
  const raw = href.trim();
  try {
    const u = new URL(raw, typeof window !== "undefined" ? window.location.origin : "https://dummy.local/");
    const protocol = u.protocol.replace(/:$/, "").toLowerCase();
    if (protocol === "http" || protocol === "https" || protocol === "mailto") {
      return u.toString();
    }
    if (raw.startsWith("/") || raw.startsWith("./") || raw.startsWith("../")) return raw;
  } catch {
    return undefined;
  }
  return undefined;
}

const mdComponents = {
  p({ children }: { children?: ReactNode }) {
    return <p className="mb-3 text-sm leading-relaxed last:mb-0">{children}</p>;
  },
  strong({ children }: { children?: ReactNode }) {
    return <strong className="font-semibold">{children}</strong>;
  },
  em({ children }: { children?: ReactNode }) {
    return <em>{children}</em>;
  },
  del({ children }: { children?: ReactNode }) {
    return <del className="opacity-85">{children}</del>;
  },
  a({ href, children }: { href?: string; children?: ReactNode }) {
    const safe = sanitizeHref(href);
    if (!safe) return <span className="text-muted-foreground">{children}</span>;
    return (
      <a href={safe} target="_blank" rel="noopener noreferrer" className="font-medium underline underline-offset-2">
        {children}
      </a>
    );
  },
  ul({ children }: { children?: ReactNode }) {
    return <ul className="mb-3 list-disc pl-6 text-sm leading-relaxed last:mb-0">{children}</ul>;
  },
  ol({ children }: { children?: ReactNode }) {
    return <ol className="mb-3 list-decimal pl-6 text-sm leading-relaxed last:mb-0">{children}</ol>;
  },
  li({ children }: { children?: ReactNode }) {
    return <li className="mt-1.5">{children}</li>;
  },
  blockquote({ children }: { children?: ReactNode }) {
    return (
      <blockquote className="mb-3 border-l-2 border-muted-foreground/35 pl-3 text-muted-foreground last:mb-0 [&>p]:text-muted-foreground">
        {children}
      </blockquote>
    );
  },
  code({ children, className }: { children?: ReactNode; className?: string }) {
    const inline = typeof className === "undefined" || !className?.includes("language-");
    if (inline) {
      return <code className={inlineCodeClass}>{children}</code>;
    }
    return (
      <code className={cn(inlineCodeClass, "my-3 block whitespace-pre-wrap p-3 text-[0.8rem] leading-snug")}>
        {children}
      </code>
    );
  },
  pre({ children }: { children?: ReactNode }) {
    return <pre className="my-3 overflow-x-auto rounded-md border border-border bg-muted/40 p-0 text-[0.8rem]">{children}</pre>;
  },
  h2({ children }: { children?: ReactNode }) {
    return <h2 className="mb-2 text-sm font-semibold tracking-tight">{children}</h2>;
  },
  h3({ children }: { children?: ReactNode }) {
    return <h3 className="mb-2 text-sm font-semibold tracking-tight">{children}</h3>;
  },
  hr() {
    return <hr className="my-4 border-border" />;
  },
} satisfies JSX.IntrinsicElements extends never
  ? Record<string, unknown>
  : Record<string, (props: { children?: ReactNode; href?: string; className?: string }) => JSX.Element>;

export type EmailThreadMarkdownBodyProps = {
  markdown: string;
