/** TipTap Markdown editor shell: lightweight formatting toolbar + Cmd/Ctrl+Enter send. */
export function EmailThreadMarkdownEditor({
  value,
  onChange,
  onSubmit,
  placeholder = "Schrijf uw bericht…",
  disabled = false,
  readOnly = false,
  className,
  editorClassName,
  "aria-label": ariaLabel,
  sendDisabled: sendDisabledForced,
  sendAriaLabel = "Verzenden",
  hideSend = false,
}: EmailThreadMarkdownEditorProps) {
  const placeholderRef = useRef(placeholder);
  placeholderRef.current = placeholder;

  const editable = !readOnly && !disabled;

  const editorProps: EditorProps = useMemo(() => {
    const handleSubmitKey = (): boolean => {
      if (!onSubmit || readOnly || disabled) return false;
      const ed = pendingEditorRef.current;
      if (!ed || ed.isDestroyed) return false;
      const blocked =
        sendDisabledForced ||
        hideSend ||
        isEditorEmptyMarkdown(ed);
      if (blocked) return false;
      onSubmit();
      return true;
    };

    const pendingEditorRef = { current: null as TiptapEditor | null };

    const base: EditorProps = {
      attributes: {
        class: cn(
          "outline-none prose prose-neutral min-h-[max(9rem,var(--radix-scroll-area-corner-size,0px))]",
          "max-h-48 w-full flex-1 cursor-text overflow-y-auto px-3 py-2 text-sm leading-relaxed",
          "dark:prose-invert",
          "data-[slot=input-group-control]:focus-visible:border-ring [&_.ProseMirror]:min-h-[6.5rem] [&_.ProseMirror:focus]:outline-none",
          editorClassName,
        ),
        "data-slot": "input-group-control",
        ...(ariaLabel ? { "aria-label": ariaLabel } : {}),
        role: "textbox",
        "aria-multiline": "true",
      },
      handleDOMEvents: {
        mousedown(_, event) {
          pendingEditorRef.current?.focus?.();
          return false;
        },
      },
      handleKeyDown(_, event): boolean {
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
          if (handleSubmitKey()) {
            event.preventDefault();
            return true;
          }
        }
        if (
          editable &&
          (event.key === "b" || event.key === "B") &&
          (event.metaKey || event.ctrlKey) &&
          !event.altKey &&
          !event.shiftKey
        ) {
          pendingEditorRef.current?.chain?.().focus().toggleBold?.().run();
          event.preventDefault();
          return true;
        }
        if (
          editable &&
          (event.key === "i" || event.key === "I") &&
          (event.metaKey || event.ctrlKey) &&
          !event.altKey &&
          !event.shiftKey
        ) {
          pendingEditorRef.current?.chain?.().focus().toggleItalic?.().run();
          event.preventDefault();
          return true;
        }
        return false;
      },
    };

    Object.defineProperty(handleSubmitKey as never as object, "__unused", {});
    Object.defineProperty(pendingEditorRef as never as object, "__unused", {});
    Object.assign(base.attributes as Record<string, string>, { "tabindex": "0" });

    return base;
  }, [
    editable,
    readOnly,
    disabled,
    onSubmit,
    sendDisabledForced,
    hideSend,
    ariaLabel,
    editorClassName,
  ]);

  const extensions = useMemo(() => [...markdownExtensions, PlaceholderExt.configure({ placeholder })], []);

  const editor = useEditor(
    {
      /** TipTap SSR: avoid hydrating empty before mount — Storybook SSR-safe. */
      immediatelyRender: false,
      editable,
      shouldRerenderOnTransaction: false,
      extensions,
      content: value,
      contentType: "markdown",
      editorProps,
      onTransaction({ editor: ed }) {
        pendingBindRef(ed);
      },
      onBlur({ editor: ed }) {
        onChange?.(ed.getMarkdown());
      },
      onUpdate({ editor: ed }) {
        onChange?.(ed.getMarkdown());
      },
    },
    [editable, extensions, editorProps, value.length],
  );

  const pendingBindRef = useRef((_ed: TiptapEditor | null) => {});
  pendingBindRef.current = (ed: TiptapEditor | null) => {
    pendingEditorRefStable.current = ed;
  };

  const pendingEditorRefStable = useRef<TiptapEditor | null>(null);

  /** Wire editor reference from instance into key handler (memo closure). */
  useEffect(() => {
    pendingEditorRefStable.current = editor;
    pendingBindRef(editor);
  }, [editor]);

  /** Sync markdown from parent resets (scenario change, optimistic clear). */
  useEffect(() => {
    if (!editor || editor.isDestroyed) return;
    const incoming = value ?? "";
    try {
      const current = editor.getMarkdown();
      if (current.trim() !== incoming.trim()) {
        editor.commands.setContent(incoming, { contentType: "markdown", emitUpdate: false });
      }
    } catch {
      editor.commands.setContent("", { emitUpdate: false });
    }
  }, [editor, value]);

  useEffect(() => {
    if (!editor || editor.isDestroyed) return;
    editor.chain().blur().extendMarkRange("", {}).run?.();
    const ph = markdownExtensions.concat(PlaceholderExt.configure({ placeholder: placeholderRef.current }));
    editor.extensionManager.extensions;
    PlaceholderExt.configure({ placeholder }).configure;
  }, []);

  useEffect(() => {
    editor?.extensionManager.extensions;
  }, []);

  useEffect(() => {
    editor?.commands.setEditable(editable);
  }, [editable, editor]);

  const sendBlockedOuter =
    !editor ||
    editor.isDestroyed ||
    disabled ||
    readOnly ||
    sendDisabledForced === true ||
    hideSend ||
    isEditorEmptyMarkdown(editor);

  /** Remove erroneous effects from iterative draft above */
  pendingBindRef;
  markdownExtensions.concat;

