export type EmailThreadMarkdownEditorProps = {
  value: string;
  onChange?: (markdown: string) => void;
  onSubmit?: () => void;
  placeholder?: string;
  disabled?: boolean;
  readOnly?: boolean;
  /** When true and `onSubmit` is set, the send control is type="button" (parent supplies `<form>`). */
  nestedInForm?: boolean;
  "aria-label"?: string;
  className?: string;
  editorClassName?: string;
  /** Disable send UI even when there is editable content. */
  sendDisabled?: boolean;
  sendAriaLabel?: string;
  /** Hide send control (keyboard submit may still fire if wired). */
  hideSend?: boolean;
};

function isEditorMarkdownEmpty(editor: TiptapEditor): boolean {
  try {
    if (editor.isEmpty) return true;
    return editor.getMarkdown().replace(/\u00a0|\s+/g, "").length === 0;
  } catch {
    return true;
  }
}

export function EmailThreadMarkdownEditor({
  value,
  onChange,
  onSubmit,
  placeholder = "Schrijf uw bericht…",
  disabled = false,
  readOnly = false,
  nestedInForm = false,
  className,
  editorClassName,
  "aria-label": ariaLabel = placeholder,
  sendDisabled: sendForcedDisabled,
  sendAriaLabel = "Verzenden",
  hideSend = false,
}: EmailThreadMarkdownEditorProps) {
  const editorApiRef = useRef<TiptapEditor | null>(null);
  const onChangeRef = useRef(onChange);
  const onSubmitRef = useRef(onSubmit);
  const blockedRef = useRef({
    readOnly,
    disabled,
    sendForced: Boolean(sendForcedDisabled),
    hideSend,
  });

  onChangeRef.current = onChange;
  onSubmitRef.current = onSubmit;
  blockedRef.current = {
    readOnly,
    disabled,
    sendForced: Boolean(sendForcedDisabled),
    hideSend,
  };

  const editable = !readOnly && !disabled;

  const modifierKeyLabel = useMemo(() => {
    if (typeof navigator === "undefined") return "Ctrl";
    return /Mac|iPhone|iPad|iPod/i.test(navigator.platform) ? "⌘" : "Ctrl";
  }, []);

  const editorProps: EditorProps = useMemo(
    () => ({
      attributes: {
        class: cn(
          "outline-none",
          "[&_.ProseMirror]:min-h-[7rem] [&_.ProseMirror]:w-full [&_.ProseMirror]:cursor-text [&_.ProseMirror]:px-3 [&_.ProseMirror]:py-2",
          "[&_.ProseMirror:focus]:outline-none",
          "[&_.ProseMirror_p]:my-2 [&_.ProseMirror_p:first-child]:mt-0 [&_.ProseMirror_p:last-child]:mb-2",
          "[&_.ProseMirror_ul]:my-2 [&_.ProseMirror_ol]:my-2 [&_.ProseMirror_blockquote]:my-2 [&_.ProseMirror_h2,&_.ProseMirror_h3]:mt-3 [&_.ProseMirror_h2,&_.ProseMirror_h3]:mb-2",
          "max-h-48 overflow-y-auto text-sm leading-relaxed text-foreground",
          "data-slot=input-group-control",
          editorClassName,
        ),
        tabindex: "0",
        spellcheck: "true",
        ...(ariaLabel ? { "aria-label": ariaLabel, role: "textbox" } : { role: "textbox" }),
      },
      handleKeyDown(_, event) {
        const editor = editorApiRef.current;
        if (!editor || editor.isDestroyed) return false;
        const b = blockedRef.current;

        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
          if (
            !b.readOnly &&
            !b.disabled &&
            onSubmitRef.current &&
            !b.hideSend &&
            !b.sendForced &&
            !isEditorMarkdownEmpty(editor)
          ) {
            event.preventDefault();
            onSubmitRef.current();
            return true;
          }
        }

        const mod = event.metaKey || event.ctrlKey;
        if (!b.readOnly && !b.disabled && mod && !event.altKey) {
          if (event.key === "b" || event.key === "B") {
            event.preventDefault();
            editor.chain().focus().toggleBold().run();
            return true;
          }
          if (event.key === "i" || event.key === "I") {
            event.preventDefault();
            editor.chain().focus().toggleItalic().run();
            return true;
          }
        }
        return false;
      },
    }),
    [ariaLabel, editorClassName],
  );

  const extensions = useMemo(
    () => [...baseMarkdownExtensionsWithoutPlaceholder, PlaceholderExt.configure({ placeholder })],
    [placeholder],
  );

  const editor = useEditor(
    {
      immediatelyRender: false,
      /** Prototype / Storybook SSR — mount before first paint mismatch. */
      shouldRerenderOnTransaction: false,
      extensions,
      content: value,
      contentType: "markdown",
      editorProps,
      onCreate({ editor }) {
        editorApiRef.current = editor;
      },
      onDestroy() {
        editorApiRef.current = null;
      },
      onUpdate({ editor }) {
        onChangeRef.current?.(editor.getMarkdown());
      },
    },
    [extensions, editorProps],
  );

  useEffect(() => {
    if (!editor || editor.isDestroyed) return;
    editor.commands.setEditable(editable);
  }, [editor, editable]);

  useEffect(() => {
    if (!editor || editor.isDestroyed) return;
    const next = value ?? "";
    try {
      const cur = editor.getMarkdown();
      if (cur.trim() !== next.trim()) {
        editor.commands.setContent(next, { contentType: "markdown", emitUpdate: false });
      }
    } catch {
      editor.commands.clearContent(false);
    }
  }, [editor, value]);

  const submit = () => {
    const b = blockedRef.current;
    const ed = editorApiRef.current;
    if (
      b.readOnly ||
      b.disabled ||
      !ed ||
      ed.isDestroyed ||
      b.hideSend ||
      b.sendForced ||
      !onSubmitRef.current ||
      isEditorMarkdownEmpty(ed)
    )
      return;
    onSubmitRef.current();
  };

  const showSend = Boolean(onSubmit) && !hideSend && !readOnly;
  const sendBlockedOuter =
    !editor ||
    editor.isDestroyed ||
    blockedRef.current.disabled ||
    blockedRef.current.readOnly ||
    blockedRef.current.hideSend ||
    blockedRef.current.sendForced ||
    isEditorMarkdownEmpty(editor);

  const toolbarDisabled = disabled || readOnly || !editor;

  const lockRadius =
    "hover:!rounded-[calc(var(--radius)-3px)] aria-expanded:!rounded-[calc(var(--radius)-3px)]";

  const editorSurface = editor ? (
    <EditorContent editor={editor} className="w-full shrink-0" />
  ) : (
    <div
      aria-hidden
      className={cn(
        "min-h-[7rem] w-full shrink-0 rounded-md border border-transparent bg-muted/25 px-3 py-2",
        "[background-image:linear-gradient(90deg,transparent,var(--muted-foreground)_12%,transparent)]",
      )}
      style={{ animation: `pulse 3s cubic-bezier(.4,0,.6,1) infinite`, backgroundSize: "200%" }}
    />
  );

  const addons = editor ? (
    <InputGroupAddon align="block-end" className="flex flex-row flex-wrap items-center gap-micro border-t pb-2">
      <TooltipProvider delayDuration={300}>
        <Tooltip>
          <TooltipTrigger asChild>
            <span>
              <InputGroupButton
                type="button"
                variant={editor.isActive("bold") ? "secondary" : "ghost"}
                size="icon-xs"
                disabled={toolbarDisabled}
                aria-pressed={editor.isActive("bold")}
                aria-label="Vet"
                className={lockRadius}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => editor.chain().focus().toggleBold().run()}
              >
                <Bold className="size-3.5" strokeWidth={1.65} aria-hidden />
              </InputGroupButton>
            </span>
          </TooltipTrigger>
          <TooltipContent side="top">
            <span>Vet</span>
            <KbdGroup>
              <Kbd>{modifierKeyLabel}</Kbd>
              <Kbd>B</Kbd>
            </KbdGroup>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>

      <TooltipProvider delayDuration={300}>
        <Tooltip>
          <TooltipTrigger asChild>
            <span>
              <InputGroupButton
                type="button"
                variant={editor.isActive("italic") ? "secondary" : "ghost"}
                size="icon-xs"
                disabled={toolbarDisabled}
                aria-pressed={editor.isActive("italic")}
                aria-label="Cursief"
                className={lockRadius}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => editor.chain().focus().toggleItalic().run()}
              >
                <Italic className="size-3.5" strokeWidth={1.65} aria-hidden />
              </InputGroupButton>
            </span>
          </TooltipTrigger>
          <TooltipContent side="top">
            <span>Cursief</span>
            <KbdGroup>
              <Kbd>{modifierKeyLabel}</Kbd>
              <Kbd>I</Kbd>
            </KbdGroup>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>

      <TooltipProvider delayDuration={300}>
        <Tooltip>
          <TooltipTrigger asChild>
            <span>
              <InputGroupButton
                type="button"
                variant={editor.isActive("strike") ? "secondary" : "ghost"}
                size="icon-xs"
                disabled={toolbarDisabled}
                aria-pressed={editor.isActive("strike")}
                aria-label="Doorhalen"
                className={lockRadius}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => editor.chain().focus().toggleStrike().run()}
              >
                <Strikethrough className="size-3.5" strokeWidth={1.65} aria-hidden />
              </InputGroupButton>
            </span>
          </TooltipTrigger>
          <TooltipContent side="top">
            <span>Doorhalen</span>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>

      <div className="mx-1 h-4 w-px shrink-0 bg-border" aria-hidden />

      <InputGroupButton
        type="button"
        variant={editor.isActive("heading", { level: 2 }) ? "secondary" : "ghost"}
        size="icon-xs"
        disabled={toolbarDisabled}
        aria-pressed={editor.isActive("heading", { level: 2 })}
        aria-label="Kop niveau 2"
        className={lockRadius}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
      >
        <Heading2 className="size-3.5" strokeWidth={1.65} aria-hidden />
      </InputGroupButton>

      <InputGroupButton
        type="button"
        variant={editor.isActive("heading", { level: 3 }) ? "secondary" : "ghost"}
        size="icon-xs"
        disabled={toolbarDisabled}
        aria-pressed={editor.isActive("heading", { level: 3 })}
        aria-label="Kop niveau 3"
        className={lockRadius}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()}
      >
        <Heading3 className="size-3.5" strokeWidth={1.65} aria-hidden />
      </InputGroupButton>

      <InputGroupButton
        type="button"
        variant={editor.isActive("bulletList") ? "secondary" : "ghost"}
        size="icon-xs"
        disabled={toolbarDisabled}
        aria-pressed={editor.isActive("bulletList")}
        aria-label="Lijst met opsommingstekens"
        className={lockRadius}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => editor.chain().focus().toggleBulletList().run()}
      >
        <List className="size-3.5" strokeWidth={1.65} aria-hidden />
      </InputGroupButton>

      <InputGroupButton
        type="button"
        variant={editor.isActive("orderedList") ? "secondary" : "ghost"}
        size="icon-xs"
        disabled={toolbarDisabled}
        aria-pressed={editor.isActive("orderedList")}
        aria-label="Genummerde lijst"
        className={lockRadius}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => editor.chain().focus().toggleOrderedList().run()}
      >
        <ListOrdered className="size-3.5" strokeWidth={1.65} aria-hidden />
      </InputGroupButton>

      <InputGroupButton
        type="button"
        variant={editor.isActive("blockquote") ? "secondary" : "ghost"}
        size="icon-xs"
        disabled={toolbarDisabled}
        aria-pressed={editor.isActive("blockquote")}
        aria-label="Citaat"
        className={lockRadius}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => editor.chain().focus().toggleBlockquote().run()}
      >
        <Quote className="size-3.5" strokeWidth={1.65} aria-hidden />
      </InputGroupButton>

      <div className="flex flex-1" />

      {showSend ? (
        <TooltipProvider delayDuration={300}>
          <Tooltip>
            <TooltipTrigger asChild>
              <span className={cn(sendBlockedOuter && "pointer-events-none")}>
                <InputGroupButton
                  type={nestedInForm ? "button" : "submit"}
                  variant="default"
                  size="icon-xs"
                  aria-label={sendAriaLabel}
                  disabled={sendBlockedOuter}
                  className={cn("ml-auto", lockRadius)}
                  onMouseDown={(e) => {
                    if (nestedInForm) e.preventDefault();
                  }}
